/* Castles & Fortresses set additions — cards appended after castles-fortresses.js.
   (castles-fortresses.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'castles-fortresses.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('castles-fortresses');
  if (!S) return;
  var extra = [{"name":"Château de Cheverny","rarity":"uncommon","id":"chateau-de-cheverny","subtitle":"Castle","details":"A classical Loire château kept by the same family for centuries, famed for its interiors and hunting hounds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheverny_01.jpg?width=1024"},{"name":"Château de Foix","rarity":"uncommon","id":"chateau-de-foix","subtitle":"Castle","details":"A Cathar-era castle on a rock above Foix, its three towers long the seat of the counts of Foix.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chateau_de_Foix_FRA_001.JPG?width=1024"},{"name":"Château de Langeais","rarity":"uncommon","id":"chateau-de-langeais","subtitle":"Castle","details":"A fortress-like Loire château where Charles VIII married Anne of Brittany in 1491, uniting Brittany with France.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Parka_fasado_de_la_Ch%C3%A2teau_de_Langeais_04.jpg?width=1024"},{"name":"Château de Vincennes","rarity":"uncommon","id":"chateau-de-vincennes","subtitle":"Fortress","details":"A royal fortress east of Paris with one of Europe's tallest medieval keeps, used as palace, prison and arsenal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vincennes_-_Chateau_02.jpg?width=1024"},{"name":"Citadel of Lille","rarity":"uncommon","id":"citadel-of-lille","subtitle":"Fortress","details":"Vauban's first great citadel, a five-bastion star dubbed the Queen of Citadels, raised after France took Lille in 1667.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Citadelle_vue_du_ciel.jpg?width=1024"},{"name":"Citadel of Qaitbay","rarity":"uncommon","id":"citadel-of-qaitbay","subtitle":"Fortress","details":"A Mamluk sea fort in Alexandria built in the 1470s on the site of the ancient Pharos lighthouse.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D9%82%D9%84%D8%B9%D8%A9_%D9%82%D8%A7%D9%8A%D8%AA%D8%A8%D8%A7%D9%8A_%D9%85%D9%86_%D8%A7%D9%84%D8%AC%D9%88.jpg?width=1024"},{"name":"Corfe Castle","rarity":"uncommon","id":"corfe-castle","subtitle":"Castle","details":"Slighted by Parliament in 1646 after a Civil War siege, Corfe's shattered keep still dominates its Dorset village and gap in the Purbecks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Corfe_Castle%2C_Dorset.jpg?width=1024"},{"name":"Culzean Castle","rarity":"uncommon","id":"culzean-castle","subtitle":"Castle","details":"Robert Adam designed this cliff-top Ayrshire castle in the 1770s for the Earl of Cassillis, overlooking the Firth of Clyde.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Culzean_Castle_house_and_gardens_01.JPG?width=1024"},{"name":"De Haar Castle","rarity":"uncommon","id":"de-haar-castle","subtitle":"Castle","details":"The Netherlands' largest castle, near Utrecht, was rebuilt in grand Neo-Gothic style in the 1890s for the Van Zuylen family.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/De_Haar_castlle.jpg?width=1024"},{"name":"Devín Castle","rarity":"uncommon","id":"devin-castle","subtitle":"Castle","details":"These Slovak ruins crown a cliff where the Morava meets the Danube, a border stronghold since the age of Great Moravia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Devin02.jpg?width=1024"},{"name":"Dublin Castle","rarity":"uncommon","id":"dublin-castle","subtitle":"Castle","details":"Raised on a Viking settlement from 1204, Dublin Castle was the seat of English and British rule in Ireland for over 700 years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dublin_Dublin_Castle_Exterior_Great_Courtyard_1.jpg?width=1024"},{"name":"Dungeon","rarity":"uncommon","id":"dungeon","subtitle":"Castle Part","details":"A dungeon was a castle's lock-up for valuable prisoners awaiting ransom, serving more as a prison than a torture chamber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Muzej_Me%C4%91imurja%2C_%C4%8Cakovec_-_vrata_tamnice_u_Starom_gradu_Zrinskih.jpg?width=1024"},{"name":"Fort Aguada","rarity":"uncommon","id":"fort-aguada","subtitle":"Fort","details":"A Portuguese seaside fort of 1612 in Goa, named for the freshwater spring where ships replenished their water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_aguada.jpg?width=1024"},{"name":"Fort Carré","rarity":"uncommon","id":"fort-carre","subtitle":"Fort","details":"A four-pointed star fort on a hill above Antibes on the French Riviera, built under Henri IV in the late 1500s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort-carr%C3%A9-antibes-vue-mer.jpg?width=1024"},{"name":"Fort de Joux","rarity":"uncommon","id":"fort-de-joux","subtitle":"Fort","details":"A Jura mountain fort rebuilt across a thousand years, guarding the road from France into Switzerland at Pontarlier.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_de_Joux_02.jpg?width=1024"},{"name":"Fort Henry","rarity":"uncommon","id":"fort-henry-kingston","subtitle":"Fort","details":"A British fort of the 1830s guarding Kingston's harbour and the entrance to Ontario's Rideau Canal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Henry_Kingston_Ontario_3.jpg?width=1024"},{"name":"Fort Jesus","rarity":"uncommon","id":"fort-jesus","subtitle":"Fort","details":"A Portuguese fort in Mombasa built in the 1590s in the shape of a man, guarding the old harbor entrance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Jesus_at_the_Mombasa_Island.jpg?width=1024"},{"name":"Fort Mackinac","rarity":"uncommon","id":"fort-mackinac","subtitle":"Fort","details":"A bluff-top fort on Michigan's Mackinac Island, founded by the British in 1780 above the Straits of Mackinac.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Firing_of_the_canyon_from_Fort_Mackinac_on_Mackinac_Island.jpg?width=1024"},{"name":"Fort Morgan","rarity":"uncommon","id":"fort-morgan","subtitle":"Fort","details":"This star-shaped brick fort guards Mobile Bay in Alabama, where Farragut ordered 'Damn the torpedoes' in 1864.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FortMorgan02.jpg?width=1024"},{"name":"Fort Pickens","rarity":"uncommon","id":"fort-pickens","subtitle":"Fort","details":"The largest of three forts guarding Pensacola Bay in Florida, held by Union forces throughout the Civil War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bastion_of_Fort_Pickens.jpg?width=1024"},{"name":"Fort Snelling","rarity":"uncommon","id":"fort-snelling","subtitle":"Fort","details":"A limestone fort at the meeting of the Mississippi and Minnesota rivers, founded in 1819 as Fort St. Anthony.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FortSnellingTower.jpg?width=1024"},{"name":"Fort Union","rarity":"uncommon","id":"fort-union","subtitle":"Fort","details":"New Mexico's largest frontier fort, an adobe post that supplied and guarded traffic along the Santa Fe Trail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fortunion.JPG?width=1024"},{"name":"Fortress of Salses","rarity":"uncommon","id":"fortress-of-salses","subtitle":"Fortress","details":"Built by Spain in the 1490s at the gateway to Roussillon, its thick walls were designed to resist early cannon fire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fortress_of_Salses_%28Roussillon%29.jpg?width=1024"},{"name":"Glamis Castle","rarity":"uncommon","id":"glamis-castle","subtitle":"Castle","details":"Home of the Earls of Strathmore since 1372, Glamis in Angus is linked by legend to Shakespeare's Macbeth, Thane of Glamis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Glamis_Castle_-_geograph.org.uk_-_7848853.jpg?width=1024"},{"name":"Golconda Fort","rarity":"uncommon","id":"golconda-fort","subtitle":"Fort","details":"A ruined citadel near Hyderabad famed for its acoustic tricks, diamond trade and layered granite walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golconda_Fort_005.jpg?width=1024"},{"name":"Goryokaku","rarity":"uncommon","id":"goryokaku","subtitle":"Fort","details":"A star-shaped Western-style fort in Hakodate, completed in 1866 and now ringed by cherry trees in a public park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hakodate_Goryokaku_Panorama_1.JPG?width=1024"},{"name":"Gripsholm Castle","rarity":"uncommon","id":"gripsholm-castle","subtitle":"Palace","details":"Gustav Vasa's red-brick palace on Lake Mälaren in Sweden is famed for its well-preserved Renaissance interiors and royal portrait collection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gripsholms_slott_view2.jpg?width=1024"},{"name":"Gruyères Castle","rarity":"uncommon","id":"gruyeres-castle","subtitle":"Castle","details":"A medieval hilltop castle in the Swiss canton of Fribourg, home for centuries to the counts of Gruyères.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/12_Chateau_de_Gruy%C3%A8res_Photo_by_Giles_Laurent.jpg?width=1024"},{"name":"Hampton Court Palace","rarity":"uncommon","id":"hampton-court-palace","subtitle":"Palace","details":"Cardinal Wolsey's Thames-side palace, seized by Henry VIII, blends Tudor brick courts with a Baroque palace by Christopher Wren.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hampton_Court_Palace%2C_West_Front_Richmond_upon_Thames_1193127_20230823_0050.jpg?width=1024"},{"name":"Hikone Castle","rarity":"uncommon","id":"hikone-castle","subtitle":"Castle","details":"A moated castle by Lake Biwa whose ornate keep survives intact from the early 1600s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hikone_Castle_November_2016_-02.jpg?width=1024"},{"name":"Hluboká Castle","rarity":"uncommon","id":"hluboka-castle","subtitle":"Castle","details":"A white Neo-Gothic castle in South Bohemia modelled on Windsor, rebuilt by the Schwarzenberg family in the 19th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_hlubok%C3%A1.jpg?width=1024"},{"name":"Hoarding","rarity":"uncommon","id":"hoarding","subtitle":"Castle Part","details":"Hoarding was a roofed timber gallery hung outside a wall top, letting defenders drop missiles through its floor slots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brattice_at_Carcassonne%28France%293.JL.jpg?width=1024"},{"name":"Häme Castle","rarity":"uncommon","id":"hame-castle","subtitle":"Castle","details":"A red-brick medieval castle on Lake Vanajavesi in Hämeenlinna, Finland, later used for centuries as a prison.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hame_Castle_2019-08.jpg?width=1024"},{"name":"Inuyama Castle","rarity":"uncommon","id":"inuyama-castle","subtitle":"Castle","details":"One of Japan's twelve original keeps, a small white castle on a hill above the Kiso River in Aichi.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castle_in_Inuyama.JPG?width=1024"},{"name":"Junagarh Fort","rarity":"uncommon","id":"junagarh-fort","subtitle":"Fort","details":"Bikaner's red sandstone fort, unusual for standing on flat desert ground rather than a hilltop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/India_Bikaner_Junagarh_Fort.jpg?width=1024"},{"name":"Kalmar Castle","rarity":"uncommon","id":"kalmar-castle","subtitle":"Castle","details":"This Swedish seaside castle, reshaped in Renaissance style in the 16th century, was where the Kalmar Union was sealed in 1397.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1285Kalmar_slott.jpg?width=1024"},{"name":"Kerak Castle","rarity":"uncommon","id":"kerak-castle","subtitle":"Castle","details":"A Crusader castle in Jordan on the King's Highway, a maze of vaulted halls above a steep valley.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kerak_BW_1.JPG?width=1024"},{"name":"Kochi Castle","rarity":"uncommon","id":"kochi-castle","subtitle":"Castle","details":"The only Japanese castle where the lord's residence survives attached to its original keep, in Shikoku.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kochi_Castle_2025.jpg?width=1024"},{"name":"Konopiště Castle","rarity":"uncommon","id":"konopiste-castle","subtitle":"Castle","details":"A French-style castle near Prague that became the home of Archduke Franz Ferdinand, an avid hunter and collector.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Overview_of_Konopi%C5%A1t%C4%9B_castle%2C_Konopi%C5%A1t%C4%9B%2C_Bene%C5%A1ov%2C_Bene%C5%A1ov_District.JPG?width=1024"},{"name":"Kriebstein Castle","rarity":"uncommon","id":"kriebstein-castle","subtitle":"Castle","details":"A well-preserved medieval castle on a rocky spur above the Zschopau river in Saxony, dating from the 14th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burg_Kriebstein_%2851141665188%29.jpg?width=1024"},{"name":"Lednice Palace","rarity":"uncommon","id":"lednice-palace","subtitle":"Palace","details":"A Neo-Gothic palace in Moravia, summer seat of the Liechtenstein family amid one of Europe's largest designed landscapes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lednice%2C_z%C3%A1mek_%281%29.jpg?width=1024"},{"name":"Lindisfarne Castle","rarity":"uncommon","id":"lindisfarne-castle","subtitle":"Castle","details":"A 16th-century fort on Holy Island, remodelled by Edwin Lutyens in 1901, Lindisfarne Castle is reached by a tidal causeway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LindisfarneCastleHolyIsland.jpg?width=1024"},{"name":"Ljubljana Castle","rarity":"uncommon","id":"ljubljana-castle","subtitle":"Castle","details":"Watching over Slovenia's capital from Castle Hill, this fortress was rebuilt over centuries and once housed the city's mayor and a prison.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ljubljanski_grad_in_Grajski_gri%C4%8D.jpg?width=640"},{"name":"Marugame Castle","rarity":"uncommon","id":"marugame-castle","subtitle":"Castle","details":"A hill castle in Kagawa with some of Japan's tallest castle stone walls and steep fan-shaped slopes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marugame_Castle01.jpg?width=1024"},{"name":"Mary Queen of Scots' Imprisonment","rarity":"uncommon","id":"mary-queen-of-scots-imprisonment","subtitle":"Legend","details":"Mary, Queen of Scots was held at Loch Leven Castle from 1567; tradition celebrates her escape across the loch by boat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lochleven_west_wall.JPG?width=1024"},{"name":"Mespelbrunn Castle","rarity":"uncommon","id":"mespelbrunn-castle","subtitle":"Castle","details":"A moated Renaissance castle hidden in a Spessart valley, made famous as a location in the film The Inn in the Spessart.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wasserschloss_Mespelbrunn%2C_6_edit01.jpg?width=1024"},{"name":"Moritzburg Castle","rarity":"uncommon","id":"moritzburg-castle","subtitle":"Castle","details":"A Baroque hunting palace on an artificial lake island near Dresden, built for Augustus the Strong of Saxony.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Luftbild_Schloss_Moritzburg_2014-03-29_1.JPG?width=1024"},{"name":"Muiderslot","rarity":"uncommon","id":"muiderslot","subtitle":"Castle","details":"This moated Dutch castle near Amsterdam was built around 1285 by Count Floris V and later hosted the poet P.C. Hooft's literary circle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Muiden%2C_Muiderslot._09-05-2022._%28actm.%29_01.jpg?width=1024"},{"name":"Murder Hole","rarity":"uncommon","id":"murder-hole","subtitle":"Castle Part","details":"A murder hole is an opening in a gate passage ceiling through which defenders dropped stones, water or missiles on attackers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bodiam_murder_holes.jpg?width=1024"},{"name":"Naarden","rarity":"uncommon","id":"naarden","subtitle":"Fortress","details":"A Dutch star-fort town whose six bastions and double moats survive almost complete near Amsterdam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Luchtfoto_Naarden-Vesting.jpg?width=1024"},{"name":"Namhansanseong","rarity":"uncommon","id":"namhansanseong","subtitle":"Fortress","details":"A mountain fortress city south of Seoul, built as an emergency capital with walls snaking over ridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Khitai5.jpg?width=1024"},{"name":"Orava Castle","rarity":"uncommon","id":"orava-castle","subtitle":"Castle","details":"Built on a steep rock above the Orava River in Slovakia, this castle grew upward in tiers after a fire in 1800 led to its rebuilding as a museum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oravsk%C3%BD_hrad_%28celkov%C3%BD_pohled%29.jpg?width=1024"},{"name":"Palace of Holyroodhouse","rarity":"uncommon","id":"palace-of-holyroodhouse","subtitle":"Palace","details":"At the foot of Edinburgh's Royal Mile, Holyroodhouse grew from a 12th-century abbey into the monarch's official Scottish residence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Holyrood_Palace_-_aerial_-_2025-04-19_01_%28cropped%29.jpg?width=1024"},{"name":"Palace of the Grand Master of Rhodes","rarity":"uncommon","id":"palace-grand-master-rhodes","subtitle":"Palace","details":"Rebuilt by the Knights Hospitaller in the 14th century, this fortified palace anchored the medieval old town of Rhodes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhodes%2C_Grand_Master_Palace_02.JPG?width=1024"},{"name":"Pembroke Castle","rarity":"uncommon","id":"pembroke-castle","subtitle":"Castle","details":"Birthplace of Henry VII in 1457, Pembroke's mighty round keep stands above the Milford Haven waterway in west Wales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pembroke_Castle_-_June_2011.jpg?width=1024"},{"name":"Petrovaradin Fortress","rarity":"uncommon","id":"petrovaradin-fortress","subtitle":"Fortress","details":"This vast Austrian fortress above the Danube at Novi Sad is nicknamed the Gibraltar of the Danube for its size and tunnel network.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Petrovaradin_Fortress_%28P%C3%A9terv%C3%A1radi_v%C3%A1r%2C_Peterwardein%29.JPG?width=1024"},{"name":"Peñíscola Castle","rarity":"uncommon","id":"peniscola-castle","subtitle":"Castle","details":"A Templar-built castle on a rocky peninsula in the Mediterranean, later home to Pope Benedict XIII.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pe%C3%B1%C3%ADscola_-_aerial_view.jpg?width=1024"},{"name":"Pillnitz Castle","rarity":"uncommon","id":"pillnitz-castle","subtitle":"Palace","details":"The Saxon kings' summer palace on the Elbe at Dresden, known for its Chinese-inspired pavilions and broad riverside steps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bergpalais_Pillnitz_September_2014.JPG?width=1024"},{"name":"Plassenburg","rarity":"uncommon","id":"plassenburg","subtitle":"Fortress","details":"A Renaissance fortress above Kulmbach, Plassenburg guarded the margraves of Brandenburg-Kulmbach and their treasury.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plassenburg_oben.jpg?width=1024"},{"name":"Quinta da Regaleira","rarity":"uncommon","id":"quinta-da-regaleira","subtitle":"Palace","details":"A Romantic estate in Sintra with a flamboyant palace, chapel, grottoes and a deep initiatory well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Exterior_of_the_Quinta_da_Regaleira_20.jpg?width=1024"},{"name":"Richard the Lionheart's Captivity","rarity":"uncommon","id":"richard-the-lionhearts-captivity","subtitle":"Legend","details":"Legend says a minstrel's song helped locate Richard the Lionheart, held for ransom at Dürnstein Castle after the crusades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ruine_D%C3%BCrnstein_40MP.jpg?width=1024"},{"name":"Robin Hood and Nottingham Castle","rarity":"uncommon","id":"robin-hood-and-nottingham-castle","subtitle":"Legend","details":"Tradition links Robin Hood with Nottingham Castle, seat of his legendary foe the Sheriff of Nottingham in the ballads.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nottingham_Castle_gatehouse_01.jpg?width=1024"},{"name":"Ross Castle","rarity":"uncommon","id":"ross-castle","subtitle":"Castle","details":"A 15th-century tower house on Lough Leane in Killarney, Ross Castle was among the last Irish strongholds to fall to Cromwell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ross_Castle_on_Lough_Leane_%2815242590587%29.jpg?width=1024"},{"name":"Royal Castle, Warsaw","rarity":"uncommon","id":"royal-castle-warsaw","subtitle":"Palace","details":"Warsaw's Old Town castle-palace was the seat of Polish monarchs and was rebuilt stone by stone after its destruction in the Second World War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Royal_Castle_in_Warsaw%2C_Poland%2C_2022%2C_03.jpg?width=1024"},{"name":"Rumeli Hisarı","rarity":"uncommon","id":"rumeli-hisari","subtitle":"Fortress","details":"An Ottoman fortress thrown up on the Bosphorus in 1452 in just four months before the conquest of Constantinople.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rumeli_Hisar%C4%B1_-_Ota%C4%9Ftepeden_G%C3%B6r%C3%BCn%C3%BC%C5%9F%C3%BC.jpg?width=1024"},{"name":"Santa Bárbara Castle","rarity":"uncommon","id":"santa-barbara-castle","subtitle":"Fortress","details":"A fortress on Mount Benacantil above Alicante, with dungeons, bastions and sweeping views of the bay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_de_Santa_B%C3%A1rbara%2C_Alicante%2C_Espa%C3%B1a%2C_2014-07-04%2C_DD_54.JPG?width=1024"},{"name":"Stolpen Castle","rarity":"uncommon","id":"stolpen-castle","subtitle":"Castle","details":"A basalt hill castle in Saxony where Augustus the Strong imprisoned his mistress, the Countess of Cosel, for 49 years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Stolpen_%28Saksen%29_Germany_16.JPG?width=1024"},{"name":"Sudeley Castle","rarity":"uncommon","id":"sudeley-castle","subtitle":"Castle","details":"In the Cotswolds near Winchcombe, Sudeley was home to Catherine Parr, the last queen of Henry VIII, who is buried in its chapel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_photo_of_Sudeley_Castle.jpg?width=1024"},{"name":"The Princes in the Tower","rarity":"uncommon","id":"the-princes-in-the-tower","subtitle":"Legend","details":"Tradition says the young Edward V and his brother vanished inside the Tower of London in 1483 and were never seen again.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White_Tower_%28Tower_of_London%29.jpg?width=1024"},{"name":"Trenčín Castle","rarity":"uncommon","id":"trencin-castle","subtitle":"Castle","details":"This Slovak castle above the Váh river is known for its tall Matúš Tower and the romantic legend of its Well of Love.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trencin_Castle_030.jpg?width=1024"},{"name":"Trim Castle","rarity":"uncommon","id":"trim-castle","subtitle":"Castle","details":"The largest Norman castle in Ireland, Trim's cruciform keep was built by Hugh de Lacy from the 1170s on the River Boyne.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trim_Castle_6.jpg?width=1024"},{"name":"Turku Castle","rarity":"uncommon","id":"turku-castle","subtitle":"Castle","details":"Finland's largest surviving medieval castle, founded around 1280 at the mouth of the Aura River, served as a fortress, palace and prison.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Turkucastle_edit.jpg?width=1024"},{"name":"Vlad the Impaler at Poenari","rarity":"uncommon","id":"vlad-the-impaler-at-poenari","subtitle":"Legend","details":"Tradition links Poenari Castle to Vlad the Impaler, the Wallachian prince whose name later inspired the Dracula legend.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PoienariCastle1.jpg?width=1024"},{"name":"Yedikule Fortress","rarity":"uncommon","id":"yedikule-fortress","subtitle":"Fortress","details":"Istanbul's Fortress of Seven Towers, built into the city walls around the ceremonial Golden Gate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Istanbul_asv2021-11_img61_Yedikule.jpg?width=1024"},{"name":"Óbidos Castle","rarity":"uncommon","id":"obidos-castle","subtitle":"Castle","details":"A medieval castle crowning the walled town of Óbidos, its towers and battlements encircling whitewashed streets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_de_%C3%93bidos%2C_%C3%93bidos%2C_Portugal%2C_2021-09-09%2C_DD_24.jpg?width=1024"},{"name":"Ajloun Castle","rarity":"common","id":"ajloun-castle","subtitle":"Castle","details":"A 12th-century Muslim hill castle in Jordan built to guard iron mines and watch Crusader strongholds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ajloun_Castle.jpg?width=1024"},{"name":"Alcazaba of Almería","rarity":"common","id":"alcazaba-of-almeria","subtitle":"Fortress","details":"One of Spain's largest Moorish fortresses, rising over Almería with three walled enclosures above the port.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alcazaba_de_Almer%C3%ADa.jpg?width=1024"},{"name":"Ambras Castle","rarity":"common","id":"ambras-castle","subtitle":"Castle","details":"Archduke Ferdinand II's Renaissance castle above Innsbruck, built around his famous collections of art and curiosities.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chateau_ambras.jpg?width=1024"},{"name":"Bartizan","rarity":"common","id":"bartizan","subtitle":"Castle Part","details":"A bartizan is a small overhanging corner turret, often corbelled high on a tower, giving sentries a view down the wall face.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marv%C3%A3o_Castle_outer_wall_and_bartizan%2C_Marv%C3%A3o%2C_Portugal_julesvernex2-2.jpg?width=1024"},{"name":"Bekal Fort","rarity":"common","id":"bekal-fort","subtitle":"Fort","details":"Kerala's largest fort, a 17th-century laterite stronghold whose walls run down to the Arabian Sea at Kasaragod.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bakel_fort_Kasargod_wide_view.jpg?width=1024"},{"name":"Bent's Old Fort","rarity":"common","id":"bents-old-fort","subtitle":"Fort","details":"A reconstructed adobe trading fort on Colorado's Arkansas River, a famed rendezvous on the Santa Fe Trail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BentsFort.jpg?width=1024"},{"name":"Bergenhus Fortress","rarity":"common","id":"bergenhus-fortress","subtitle":"Fortress","details":"One of Norway's oldest fortresses, at Bergen's harbour mouth, it preserves the medieval Håkon's Hall and Rosenkrantz Tower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bergenhus.2.JPG?width=1024"},{"name":"Bečov Castle","rarity":"common","id":"becov-castle","subtitle":"Castle","details":"A West Bohemian castle famous as the hiding place of the Romanesque Reliquary of St. Maurus, concealed beneath its chapel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Be%C4%8Dov_nad_Teplou_Castle_as_seen_from_the_northern_viewpoint_01.jpg?width=1024"},{"name":"Bitchū Matsuyama Castle","rarity":"common","id":"bitchu-matsuyama-castle","subtitle":"Castle","details":"Japan's highest castle with a surviving keep, a mountain stronghold often photographed above a sea of clouds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bitchu_Matsuyama_Castle_1.JPG?width=1024"},{"name":"Bohus Fortress","rarity":"common","id":"bohus-fortress","subtitle":"Fortress","details":"Founded in 1308 on Norway's border with Sweden, this fortress in Kungälv withstood repeated sieges without falling by storm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bohus_Fortress_in_Kung%C3%A4lv.jpg?width=1024"},{"name":"Bouzov Castle","rarity":"common","id":"bouzov-castle","subtitle":"Castle","details":"A Moravian castle rebuilt in romantic style around 1900 as a summer residence of the Teutonic Order's grand master.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bouzov_hrad_-_Burg_Busau.jpg?width=1024"},{"name":"Büdingen Castle","rarity":"common","id":"budingen-castle","subtitle":"Castle","details":"A moated castle in Hesse with massive round towers, home of the princes of Ysenburg and Büdingen since the Middle Ages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_the_Schloss_B%C3%BCdingen_%28view_from_the_south%29.jpg?width=1024"},{"name":"Cape Coast Castle","rarity":"common","id":"cape-coast-castle","subtitle":"Castle","details":"A whitewashed sea fort in Ghana, enlarged by the British over a Swedish lodge on the Gold Coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cape_Coast_Castle%2C_Cape_Coast%2C_Ghana.JPG?width=1024"},{"name":"Carrickfergus Castle","rarity":"common","id":"carrickfergus-castle","subtitle":"Castle","details":"John de Courcy began this Norman castle in 1177 on the shore of Belfast Lough; it remained a garrison into the 20th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carrickfergus-castle-1.jpg?width=1024"},{"name":"Casa Loma","rarity":"common","id":"casa-loma","subtitle":"Castle","details":"A Gothic Revival mansion castle in Toronto built in the 1910s with towers, tunnels and secret passages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Exterior_of_Casa_Loma%2C_June_2012.jpg?width=1024"},{"name":"Castel dell'Ovo","rarity":"common","id":"castel-dellovo","subtitle":"Castle","details":"Naples' oldest castle stands on the islet of Megaride, where legend says the siren Parthenope was buried.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castel_dell%27_Ovo.jpg?width=1024"},{"name":"Castello Estense","rarity":"common","id":"castello-estense","subtitle":"Castle","details":"Ferrara's moated red-brick castle, built in 1385 for the Este family, is linked to their palace by a covered passageway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Il_Castello_Estense_di_Ferrara.jpg?width=1024"},{"name":"Castillo de San Marcos","rarity":"common","id":"castillo-de-san-marcos","subtitle":"Fort","details":"St. Augustine's coquina-stone star fort, the oldest masonry fort in the continental United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_view_of_the_Castillo_de_San_Marcos%2C_St._Augustine%2C_FL_2025-05-20.jpg?width=1024"},{"name":"Castillo San Felipe del Morro","rarity":"common","id":"castillo-san-felipe-del-morro","subtitle":"Fort","details":"San Juan's sea fort in Puerto Rico, six levels of Spanish walls built over 250 years to guard the harbor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_San_Felipe_Del_Morro_%2816869927311%29.jpg?width=1024"},{"name":"Castle of Almourol","rarity":"common","id":"castle-of-almourol","subtitle":"Castle","details":"A Templar castle on a small island in the Tagus, rebuilt in the 12th century on an older fortified site.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Almourol_034.jpg?width=1024"},{"name":"Castle of Guadamur","rarity":"common","id":"castle-of-guadamur","subtitle":"Castle","details":"A 15th-century castle near Toledo with a tall square keep, round corner towers and a deep moat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo2011.jpg?width=1024"},{"name":"Castle of La Mota","rarity":"common","id":"castle-of-la-mota","subtitle":"Castle","details":"A brick fortress in Medina del Campo linked to Isabella I of Castile, with a tall keep and artillery barbican.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_de_la_Mota_2021.jpg?width=1024"},{"name":"Castle of Leiria","rarity":"common","id":"castle-of-leiria","subtitle":"Castle","details":"A medieval castle above Leiria founded under Afonso Henriques, later a royal residence with a distinctive keep.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CASTELO_DE_LEIRIA.jpg?width=1024"},{"name":"Castle of Marvão","rarity":"common","id":"castle-of-marvao","subtitle":"Castle","details":"A hilltop castle in the Alentejo guarding the Spanish border, with cisterns, walls and wide frontier views.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CastillodeMarvao.jpg?width=1024"},{"name":"Castle of Monsanto","rarity":"common","id":"castle-of-monsanto","subtitle":"Castle","details":"A granite hilltop castle above Monsanto, a village built among, under and around enormous boulders.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_view_of_the_Monsanto_Castle_in_a_foggy_morning%2C_Aldeia_de_Monsanto%2C_Portugal_julesvernex2.jpg?width=1024"},{"name":"Castle Spiral Staircase","rarity":"common","id":"castle-spiral-staircase","subtitle":"Castle Part","details":"Spiral stairs in towers often turned clockwise, hampering right-handed swordsmen climbing while defenders struck down freely.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Belsay_Castle_-_spiral_staircase_-_geograph.org.uk_-_1479432.jpg?width=1024"},{"name":"Chapultepec Castle","rarity":"common","id":"chapultepec-castle","subtitle":"Palace","details":"Mexico City's hilltop castle, home to emperors and presidents, now crowning Chapultepec Park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chapultepec_Castle_Mexico_City.webp?width=1024"},{"name":"Château de Coucy","rarity":"common","id":"chateau-de-coucy","subtitle":"Castle","details":"Once home to one of medieval Europe's largest keeps, this Picardy fortress was largely ruined in 1917.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coucy-le-Ch%C3%A2teau-Auffrique_%2802%29_Ch%C3%A2teau_de_Coucy_10.jpg?width=1024"},{"name":"Château de Loches","rarity":"common","id":"chateau-de-loches","subtitle":"Castle","details":"A fortified town in the Loire with a tall medieval keep where Joan of Arc urged Charles VII to Reims.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Loches_dungeon%2C_aerial_view_from_West.jpg?width=1024"},{"name":"Château de Montségur","rarity":"common","id":"chateau-de-montsegur","subtitle":"Castle","details":"A mountaintop castle in the Pyrenees remembered as a refuge of the Cathars, besieged in 1243-44.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau_de_Monts%C3%A9gur_-_vue_a%C3%A9rienne.jpg?width=1024"},{"name":"Château de Peyrepertuse","rarity":"common","id":"chateau-de-peyrepertuse","subtitle":"Fortress","details":"A vast Cathar fortress stretched along a limestone ridge in the Corbières, sometimes called horizontal Carcassonne.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teaux_du_Pays_cathare_-_Ch%C3%A2teau_de_Peyrepertuse_-_09.jpg?width=640"},{"name":"Château de Quéribus","rarity":"common","id":"chateau-de-queribus","subtitle":"Castle","details":"A Cathar castle perched on a narrow ridge in the Corbières, among the last Cathar strongholds to fall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/130610-Queribus-03.jpg?width=1024"},{"name":"Château de Sully-sur-Loire","rarity":"common","id":"chateau-de-sully-sur-loire","subtitle":"Castle","details":"A great keep and park at the eastern gateway to the Loire châteaux, long seat of the dukes of Sully.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/France_Loiret_Sully-sur-Loire_Chateau_01.jpg?width=1024"},{"name":"Château de Tarascon","rarity":"common","id":"chateau-de-tarascon","subtitle":"Castle","details":"A white limestone fortress on the Rhône in Provence, built by the counts of Anjou and later used as a prison.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tarascon_Le_Chateau.jpg?width=1024"},{"name":"Château des Baux","rarity":"common","id":"chateau-des-baux","subtitle":"Fortress","details":"Ruins of a rock-cut fortress above Les Baux-de-Provence, once seat of lords who claimed descent from Balthazar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castle_of_Les_Baux-de-Provence_cf01.jpg?width=1024"},{"name":"Citadel of Erbil","rarity":"common","id":"citadel-of-erbil","subtitle":"Fortress","details":"A walled citadel mound in Iraqi Kurdistan, claimed among the world's oldest continuously inhabited places.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hawler_Castle.jpg?width=1024"},{"name":"Clifford's Tower","rarity":"common","id":"cliffords-tower","subtitle":"Castle","details":"The great stone keep of York Castle, built under Henry III, is named for Roger de Clifford, hanged there in 1322.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Clifford%27s_Tower_%285259021070%29.jpg?width=1024"},{"name":"Convent of Christ","rarity":"common","id":"convent-of-christ","subtitle":"Fortress","details":"The Templars' fortified convent in Tomar, famed for its round church and ornate Manueline window.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Casa_do_Cap%C3%ADtulo%2C_Convento_de_Cristo_81.jpg?width=1024"},{"name":"Crenellation","rarity":"common","id":"crenellation","subtitle":"Castle Part","details":"Crenellation is the pattern of solid merlons and open crenels along a parapet, a feature that once required a royal licence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crenellation_%285876007660%29.jpg?width=1024"},{"name":"Curtain Wall","rarity":"common","id":"curtain-wall","subtitle":"Castle Part","details":"A curtain wall is the defensive wall linking a castle's towers, enclosing the bailey behind a continuous shield of stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castle_of_Foug%C3%A8res_13.JPG?width=1024"},{"name":"Czocha Castle","rarity":"common","id":"czocha-castle","subtitle":"Castle","details":"This romantic Polish castle on Lake Leśnia was a border stronghold of Bohemian and Lusatian rulers from the 13th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Czocha_front_1.jpg?width=640"},{"name":"Cēsis Castle","rarity":"common","id":"cesis-castle","subtitle":"Castle","details":"Founded by the Livonian Brothers of the Sword in 1209, these Latvian ruins were once a grand master of the order's residence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CesuPils_2017-09-10.jpg?width=1024"},{"name":"Egeskov Castle","rarity":"common","id":"egeskov-castle","subtitle":"Castle","details":"Denmark's best-preserved Renaissance water castle stands on oak piles in a lake on Funen, built in 1554 amid fears of civil war.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Egeskov_Slot_spejling_Edit_2.jpg?width=1024"},{"name":"Enniskillen Castle","rarity":"common","id":"enniskillen-castle","subtitle":"Castle","details":"Built by the Maguires in the 15th century, Enniskillen Castle guards the crossing between Upper and Lower Lough Erne.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Enniskillen_Castle_by_Paride.JPG?width=1024"},{"name":"Fort Anne","rarity":"common","id":"fort-anne","subtitle":"Fort","details":"Canada's first administered national historic site, a star-shaped earthwork fort at Annapolis Royal, Nova Scotia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Annapolis_Royal_-_NS_-_Fort_Anne.jpg?width=1024"},{"name":"Fort Beauséjour","rarity":"common","id":"fort-beausejour","subtitle":"Fort","details":"A five-bastion French star fort on the Isthmus of Chignecto in New Brunswick, captured by Britain in 1755.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beausejour2006.jpg?width=1024"},{"name":"Fort Chambly","rarity":"common","id":"fort-chambly","subtitle":"Fort","details":"A stone fort of 1711 at the foot of the Richelieu rapids in Quebec, guarding the invasion route from New York.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Chambly_2.0.jpg?width=1024"},{"name":"Fort Dansborg","rarity":"common","id":"fort-dansborg","subtitle":"Fort","details":"A Danish sea fort of 1620 at Tranquebar in Tamil Nadu, built for the pepper trade on the Coromandel Coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Dansborg.JPG?width=1024"},{"name":"Fort Louvois","rarity":"common","id":"fort-louvois","subtitle":"Fort","details":"A small sea fort on a tidal rock off Bourcefranc in France, reachable on foot only when the tide falls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Louvois_-_Bourcefranc.jpg?width=1024"},{"name":"Fort Michilimackinac","rarity":"common","id":"fort-michilimackinac","subtitle":"Fort","details":"A reconstructed French fur-trade fort and mission village at the Straits of Mackinac in Michigan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Michilimackinac.jpg?width=1024"},{"name":"Fort Ontario","rarity":"common","id":"fort-ontario","subtitle":"Fort","details":"A star-shaped fort at Oswego on Lake Ontario, rebuilt repeatedly after wars between France, Britain and America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Ontario_5.jpg?width=1024"},{"name":"Fort Ross","rarity":"common","id":"fort-ross","subtitle":"Fort","details":"A Russian-American Company outpost founded in 1812 on the California coast north of San Francisco.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Ross%2C_California_-Fort_Ross_Blockhouse_-_panoramio.jpg?width=1024"},{"name":"Fort St George","rarity":"common","id":"fort-st-george-chennai","subtitle":"Fort","details":"Founded in 1644 at Madras, this East India Company fort houses St Mary's Church, the oldest Anglican church in India.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chennai-Fort_St._George-Ramparts%2C_Gates_etc.-WUS01501.jpg?width=1024"},{"name":"Fort Stanwix","rarity":"common","id":"fort-stanwix","subtitle":"Fort","details":"A reconstructed Revolutionary War fort in Rome, New York, whose garrison withstood a British siege in 1777.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fost_areal_image007.jpg?width=1024"},{"name":"Fort Ticonderoga","rarity":"common","id":"fort-ticonderoga","subtitle":"Fort","details":"A star fort between Lake Champlain and Lake George, contested by France, Britain and American rebels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_Ticonderoga%2C_Ticonderoga%2C_NY.jpg?width=1024"},{"name":"Fort William","rarity":"common","id":"fort-william-kolkata","subtitle":"Fort","details":"Kolkata's great fort by the Hooghly River, rebuilt by Robert Clive after the original was captured in 1756.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gates_of_Fort_William_in_Kolkata_02.jpg?width=1024"},{"name":"Fort William Henry","rarity":"common","id":"fort-william-henry","subtitle":"Fort","details":"A British fort at Lake George, New York, whose 1757 surrender was dramatised in The Last of the Mohicans.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_William_Henry_2026.jpg?width=1024"},{"name":"Fort York","rarity":"common","id":"fort-york","subtitle":"Fort","details":"Toronto's founding fort, attacked by American forces in 1813 during the War of 1812.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fort_York_2008.jpg?width=1024"},{"name":"Fortress of Louisbourg","rarity":"common","id":"fortress-of-louisbourg","subtitle":"Fortress","details":"A partly rebuilt French fortified town in Nova Scotia, once among North America's busiest seaports.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Forteresse_de_Louisbourg_-_2.JPG?width=1024"},{"name":"Framlingham Castle","rarity":"common","id":"framlingham-castle","subtitle":"Castle","details":"Ringed by 13 curtain towers but no keep, Framlingham in Suffolk sheltered Mary Tudor as she claimed the throne in 1553.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Franglingham_Castle_01.jpg?width=1024"},{"name":"Garderobe","rarity":"common","id":"garderobe","subtitle":"Castle Part","details":"A garderobe was a castle latrine built into the wall thickness, its shaft dropping waste outside, often beside chambers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Garderobe%2C_Peveril_Castle%2C_Derbyshire.jpg?width=1024"},{"name":"Goodrich Castle","rarity":"common","id":"goodrich-castle","subtitle":"Castle","details":"Above the River Wye near Ross, Goodrich grew from a Norman keep into a strong Marcher lordship castle of the de Valence earls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Goodrich_above.jpg?width=1024"},{"name":"Great Zimbabwe","rarity":"common","id":"great-zimbabwe","subtitle":"Fortress","details":"A medieval stone city in Zimbabwe whose dry-stone Great Enclosure walls stand without any mortar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Conical_Tower_-_Great_Enclosure_III_%2833736918448%29.jpg?width=1024"},{"name":"Hohenems Palace","rarity":"common","id":"hohenems-palace","subtitle":"Palace","details":"A Renaissance palace in Vorarlberg where two manuscripts of the Nibelungenlied were discovered in its library.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palast_Hohenems_Frontpanorama_1.jpg?width=1024"},{"name":"Hohenschwangau Castle","rarity":"common","id":"hohenschwangau-castle","subtitle":"Castle","details":"The childhood home of Ludwig II, this yellow Gothic Revival castle stands opposite Neuschwanstein near the Alpsee.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Hohenschwangau_2021.jpg?width=1024"},{"name":"Kidwelly Castle","rarity":"common","id":"kidwelly-castle","subtitle":"Castle","details":"A Norman foundation rebuilt in stone from the 1270s, Kidwelly guards the River Gwendraeth in Carmarthenshire.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kidwelly_castle_whole.JPG?width=1024"},{"name":"Kreuzenstein Castle","rarity":"common","id":"kreuzenstein-castle","subtitle":"Castle","details":"A castle north of Vienna rebuilt in the 19th century from medieval stones and fittings gathered from across Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leobendorf_-_Burg_Kreuzenstein_%282%29.JPG?width=1024"},{"name":"Křivoklát Castle","rarity":"common","id":"krivoklat-castle","subtitle":"Castle","details":"A royal hunting castle in the Bohemian forests west of Prague, once a prison for the alchemist Edward Kelley.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Krivoklat_castle_01.jpg?width=1024"},{"name":"Lamu Fort","rarity":"common","id":"lamu-fort","subtitle":"Fort","details":"A massive stone fort in Lamu Town, Kenya, built in the early 1800s with coral stone and mangrove timber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LamuFort.jpg?width=1024"},{"name":"Lancaster Castle","rarity":"common","id":"lancaster-castle","subtitle":"Castle","details":"A Norman fortress on a Roman fort site, Lancaster Castle served for centuries as a court and prison in the north-west.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lancaster_Castle_-_2023-03-25.jpg?width=1024"},{"name":"Loket Castle","rarity":"common","id":"loket-castle","subtitle":"Castle","details":"A 12th-century castle on a rock looped by the Ohře river, guarding the old road into Bohemia near Karlovy Vary.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/071107-Loket-Castle-Hrad.jpg?width=1024"},{"name":"Lutsk Castle","rarity":"common","id":"lutsk-castle","subtitle":"Castle","details":"Also called Lubart's Castle, this Ukrainian stronghold in Lutsk retains three towers, including its brick Entrance Tower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lutsk_castle_tower.jpg?width=1024"},{"name":"Läckö Castle","rarity":"common","id":"lacko-castle","subtitle":"Castle","details":"This whitewashed Swedish castle on a Lake Vänern promontory was reshaped in Baroque style by Magnus Gabriel De la Gardie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/0283L%C3%A4ck%C3%B6_slott.jpg?width=1024"},{"name":"Merlon","rarity":"common","id":"merlon","subtitle":"Castle Part","details":"A merlon is one solid block of a battlement, wide enough to shield an archer who shot through the crenel beside it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Horizon_cr%C3%A9neaux_Alcazaba%2C_Almeria%2C_Spain.jpg?width=1024"},{"name":"Middleham Castle","rarity":"common","id":"middleham-castle","subtitle":"Castle","details":"The childhood home of Richard III in Wensleydale, Middleham was the great northern stronghold of the Neville family.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MiddlehamCJW.jpg?width=1024"},{"name":"Mildenburg Castle","rarity":"common","id":"mildenburg-castle","subtitle":"Castle","details":"Built around 1200 above Miltenberg on the Main, this castle guarded the river bend and the walled town below it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Miltenberg%2C_Mildenburg-001a.jpg?width=1024"},{"name":"Morro Castle, Havana","rarity":"common","id":"morro-castle-havana","subtitle":"Fort","details":"A Spanish fort guarding Havana Bay since 1589, marked by a lighthouse on its ramparts above the sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Havana_-_Morro_Castle_in_a_thunderstorm.jpg?width=1024"},{"name":"Moszna Castle","rarity":"common","id":"moszna-castle","subtitle":"Castle","details":"A fantastical Polish palace-castle in Opole Voivodeship, famed for its 99 towers and spires and its parkland setting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Mosznej_2024.jpg?width=1024"},{"name":"Motte","rarity":"common","id":"motte","subtitle":"Castle Part","details":"A motte was the steep earthen mound at the heart of early Norman castles, crowned first by timber, later by stone towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Clough_Castle_Motte_and_Bailey.jpg?width=1024"},{"name":"Muncaster Castle","rarity":"common","id":"muncaster-castle","subtitle":"Castle","details":"Above the River Esk in Cumbria, Muncaster has been held by the Pennington family since the 13th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Muncaster_Castle_-_geograph.org.uk_-_1980832.jpg?width=1024"},{"name":"Nakagusuku Castle","rarity":"common","id":"nakagusuku-castle","subtitle":"Castle","details":"Okinawa gusuku ruins whose elegant curved limestone walls overlook both the Pacific and the East China Sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nakagusuku_Castle25bs3104.jpg?width=1024"},{"name":"Narva Castle","rarity":"common","id":"narva-castle","subtitle":"Fortress","details":"Also called Hermann Castle, this Estonian fortress on the Narva River faces Russia's Ivangorod Fortress across the border.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Narva_asv2022-04_img09_Castle.jpg?width=1024"},{"name":"Olesko Castle","rarity":"common","id":"olesko-castle","subtitle":"Castle","details":"One of Ukraine's oldest castles, this oval hilltop fortress near Lviv was the birthplace of King John III Sobieski.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Olesko_Castle.jpg?width=1024"},{"name":"Orford Castle","rarity":"common","id":"orford-castle","subtitle":"Castle","details":"Henry II built Orford's unusual polygonal keep in the 1160s to assert royal power over the Suffolk coast and its barons.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orford_Castle_-_geograph.org.uk_-_8004602.jpg?width=1024"},{"name":"Oubliette","rarity":"common","id":"oubliette","subtitle":"Castle Part","details":"An oubliette was a bottle-shaped pit dungeon reached only by a trapdoor above, its name drawn from the French for forgetting.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oubliettes_du_ch%C3%A2teau_de_Miolans_%28avril_2019%29.JPG?width=1024"},{"name":"Palakkad Fort","rarity":"common","id":"palakkad-fort","subtitle":"Fort","details":"A granite fort in Kerala built by Hyder Ali in 1766, later held by the British and famed for its moated walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palakkad_Tipu_Fort.jpg?width=1024"},{"name":"Pendennis Castle","rarity":"common","id":"pendennis-castle","subtitle":"Castle","details":"Henry VIII built Pendennis in 1540 to defend Falmouth's harbour entrance against invasion from France and Spain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pendennis_Castle.jpg?width=1024"},{"name":"Pernštejn Castle","rarity":"common","id":"pernstejn-castle","subtitle":"Castle","details":"A marble-clad Gothic castle in Moravia that kept its medieval form through the centuries and was never conquered.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Pern%C5%A1tejn.jpg?width=1024"},{"name":"Pidhirtsi Castle","rarity":"common","id":"pidhirtsi-castle","subtitle":"Palace","details":"A fortified palace in Ukraine's Lviv region, built in the 1630s with bastions, gardens and a church in late Renaissance style.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/46-203-0010_Pidhirci_DSC_4252.jpg?width=1024"},{"name":"Postern Gate","rarity":"common","id":"postern-gate","subtitle":"Castle Part","details":"A postern was a small, discreet secondary gate, letting garrisons slip out, bring in supplies or escape unnoticed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Poterne_remparts_de_Provins.JPG?width=640"},{"name":"Powis Castle","rarity":"common","id":"powis-castle","subtitle":"Castle","details":"A red sandstone fortress of the princes of Powys from the 13th century, Powis overlooks famous terraced gardens near Welshpool.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Powis_Castle_2016_116_%28cropped%29.jpg?width=1024"},{"name":"Raby Castle","rarity":"common","id":"raby-castle","subtitle":"Castle","details":"Built by the Nevilles in the 14th century, Raby in County Durham is ringed by a deer park and medieval curtain walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Raby_Castle_%28spring%29.jpg?width=1024"},{"name":"Raglan Castle","rarity":"common","id":"raglan-castle","subtitle":"Castle","details":"Begun in the 1430s, Raglan in Monmouthshire was among the last great medieval castles built in Wales, famed for its moated tower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Raglan_Castle%27s_main_entrance.jpg?width=1024"},{"name":"Rapperswil Castle","rarity":"common","id":"rapperswil-castle","subtitle":"Castle","details":"A castle on a hill above Lake Zurich, founded in the 13th century at the narrow eastern end of the lake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View_of_Rapperswil_Castle%2C_20250330_0842_7844.jpg?width=1024"},{"name":"Richmond Castle","rarity":"common","id":"richmond-castle","subtitle":"Castle","details":"Begun in 1071 by Alan Rufus, Richmond in Yorkshire preserves one of England's earliest Norman stone great halls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Richmond_Castle_%288015%29.jpg?width=1024"},{"name":"Riegersburg Castle","rarity":"common","id":"riegersburg-castle","subtitle":"Castle","details":"Perched on a volcanic rock in Styria, this great fortress-castle was built up to guard the region's eastern border.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Riegersburg_Burg_Q1.jpg?width=1024"},{"name":"Riga Castle","rarity":"common","id":"riga-castle","subtitle":"Castle","details":"Rebuilt many times on the Daugava River, this Latvian castle is the official residence of the President of Latvia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_de_Riga%2C_Letonia%2C_2012-08-07%2C_DD_04.JPG?width=1024"},{"name":"Ringwork","rarity":"common","id":"ringwork","subtitle":"Castle Part","details":"A ringwork was a circular Norman earthwork, its bank and ditch ringed by a palisade and enclosing a small fortified yard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Newington_Bagpath_Motte.jpg?width=1024"},{"name":"Rocca Calascio","rarity":"common","id":"rocca-calascio","subtitle":"Fortress","details":"At about 1,460 metres, this ruined mountain fortress in Abruzzo is among the highest fortresses in the Apennines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castello_di_Rocca_Calascio_%2889629%29.jpg?width=640"},{"name":"Rochlitz Castle","rarity":"common","id":"rochlitz-castle","subtitle":"Castle","details":"A castle above the Zwickauer Mulde in Saxony whose history reaches back to a Slavic stronghold of the 10th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rochlitz_-_Blick_von_der_Mulde_zum_Schloss_%2802-3%29.jpg?width=640"},{"name":"Rosenborg Castle","rarity":"common","id":"rosenborg-castle","subtitle":"Palace","details":"Christian IV's Dutch Renaissance palace in Copenhagen now guards Denmark's crown jewels in its treasury.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/I12_174_Schloss_Rosenborg.jpg?width=1024"},{"name":"Sagunto Castle","rarity":"common","id":"sagunto-castle","subtitle":"Fortress","details":"A long hilltop fortress above Sagunto layered with Iberian, Roman, Moorish and medieval walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo04_Sagunto.JPG?width=1024"},{"name":"Sally Port","rarity":"common","id":"sally-port","subtitle":"Castle Part","details":"A sally port is a small hidden gate from which defenders could burst out to raid besiegers and burn their siege works.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Medieval_sally-port_on_north_enceinte%2C_Citadel%2C_Victoria%2C_Gozo.jpg?width=1024"},{"name":"San Carlos de la Cabaña","rarity":"common","id":"san-carlos-de-la-cabana","subtitle":"Fortress","details":"Havana's vast Spanish fortress of the 1770s, among the largest colonial fortifications in the Americas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Entrance_to_fortress_La_Caba%C3%B1a%2C_Havana%2C_Cuba.jpg?width=1024"},{"name":"Scarborough Castle","rarity":"common","id":"scarborough-castle","subtitle":"Castle","details":"Henry II's great tower crowns a headland fortress above Scarborough that was besieged repeatedly in the Civil War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scarborough_-_Castle_-_3.jpg?width=1024"},{"name":"Seggau Castle","rarity":"common","id":"seggau-castle","subtitle":"Castle","details":"A castle above Leibnitz in Styria, beside a Romanesque basilica, with roots as a stronghold of the Salzburg bishops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leibnitz_-_Schloss_Seggau_%28a%29.JPG?width=1024"},{"name":"Sidon Sea Castle","rarity":"common","id":"sidon-sea-castle","subtitle":"Castle","details":"A small Crusader sea castle on an island off Sidon, Lebanon, joined to the shore by a stone causeway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SidonSeaCastle.jpg?width=1024"},{"name":"Siege of Candia","rarity":"common","id":"siege-of-candia","subtitle":"Siege","details":"The siege of Candia in Crete lasted from 1648 to 1669, among the longest sieges in history, before the Venetians yielded.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castello_Veneziano_di_Candia_-_Heraklion.jpg?width=1024"},{"name":"Sigüenza Castle","rarity":"common","id":"siguenza-castle","subtitle":"Castle","details":"A fortress in Guadalajara rebuilt from Moorish origins, long the fortified residence of the bishops of Sigüenza.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo_de_Sig%C3%BCenza_%281337528210%29.jpg?width=1024"},{"name":"Skipton Castle","rarity":"common","id":"skipton-castle","subtitle":"Castle","details":"Built from 1090 in Yorkshire, Skipton withstood a three-year Civil War siege and is roofed by a yew tree planted in 1659.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skipton_Castle_-_geograph.org.uk_-_8209185.jpg?width=1024"},{"name":"Solar","rarity":"common","id":"solar","subtitle":"Castle Part","details":"The solar was the lord's family's private upper chamber, a sunlit retreat away from the noise and smoke of the great hall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bunratty_Castle_South_Solar_01.jpg?width=1024"},{"name":"Spangenberg Castle","rarity":"common","id":"spangenberg-castle","subtitle":"Castle","details":"A hilltop castle and later hunting lodge above the Hessian town of Spangenberg, first built in the 13th century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial_image_of_the_Spangenberg_Castle_%28view_from_the_southwest%29.jpg?width=1024"},{"name":"Takeda Castle","rarity":"common","id":"takeda-castle","subtitle":"Castle","details":"Ruined stone walls on a Hyogo mountaintop, famous for floating above morning mist like a castle in the sky.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%E7%AB%B9%E7%94%B0%E5%9F%8E.JPG?width=1024"},{"name":"Tarasp Castle","rarity":"common","id":"tarasp-castle","subtitle":"Castle","details":"A striking hilltop castle in the Lower Engadine, built in the 11th century to command the route through the Inn valley.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/160618_Schloss_Tarasp_3.jpg?width=1024"},{"name":"Tattershall Castle","rarity":"common","id":"tattershall-castle","subtitle":"Castle","details":"Lord Treasurer Ralph Cromwell built this red-brick tower in Lincolnshire in the 1430s, a showpiece of early brick building.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tattershall_Castle%2C_Lincolnshire_-_August_2014.JPG?width=1024"},{"name":"The Man in the Iron Mask","rarity":"common","id":"the-man-in-the-iron-mask","subtitle":"Legend","details":"Legend tells of a prisoner kept masked for decades at Fort Royal on Sainte-Marguerite island; his identity was never proved.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Prison_masque_de_Fer_interieur.jpg?width=1024"},{"name":"Thun Castle","rarity":"common","id":"thun-castle","subtitle":"Castle","details":"Built by the dukes of Zähringen around 1190, this castle's massive keep overlooks the town and lake of Thun in Switzerland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thun_Castle_%28Schloss_Thun%29_from_above_130622.jpg?width=1024"},{"name":"Toompea Castle","rarity":"common","id":"toompea-castle","subtitle":"Castle","details":"Tallinn's hilltop castle, seat of Estonia's parliament, layers Danish, Teutonic, Swedish and Russian building phases.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Toompea_loss_2014.jpg?width=1024"},{"name":"Tratzberg Castle","rarity":"common","id":"tratzberg-castle","subtitle":"Castle","details":"A Renaissance castle in Tyrol's Inn valley, preserved with original furnishings, an armoury and painted courtyards.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Tratzberg_012.jpg?width=1024"},{"name":"Turaida Castle","rarity":"common","id":"turaida-castle","subtitle":"Castle","details":"This red-brick Latvian castle above the Gauja River was built from 1214 for the Archbishop of Riga and partly rebuilt in modern times.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Turaida_Castle.JPG?width=1024"},{"name":"Turret","rarity":"common","id":"turret","subtitle":"Castle Part","details":"A turret is a small tower rising from a wall or corner, widening the view for watchmen and flanking fire along the defences.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tour_de_Belem_detail_1_082006.JPG?width=1024"},{"name":"Uwajima Castle","rarity":"common","id":"uwajima-castle","subtitle":"Castle","details":"A small hill castle in Ehime, one of twelve with an original keep, overlooking Uwajima Bay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Uwajima_Castle_Keep_Tower_20170611.jpg?width=1024"},{"name":"Vadstena Castle","rarity":"common","id":"vadstena-castle","subtitle":"Castle","details":"A Renaissance fortress-palace on Lake Vättern in Sweden, founded by Gustav Vasa in 1545 to defend the realm's heartland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vadstena_slott_01.jpg?width=1024"},{"name":"Wall Walk","rarity":"common","id":"wall-walk","subtitle":"Castle Part","details":"The wall walk ran along the top of the defences behind the parapet, letting guards patrol and rush to any threatened point.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ChemindeRonde.JPG?width=1024"},{"name":"Warkworth Castle","rarity":"common","id":"warkworth-castle","subtitle":"Castle","details":"A Percy stronghold above the River Coquet, Warkworth is crowned by a cross-shaped great tower built around 1400.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Warkworth_Castle%2C_Northumberland.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
